"""Random (a, b) pairs, weighted towards negative a, negative b, and
values right around the INT_MIN/-1 special case -- but never landing
exactly on it, since that combination is exercised by the fixed tests."""

INT_MIN = -2147483648


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    rows = []
    for _ in range(4):
        b = rng.choice([-7, -5, -3, -2, 2, 3, 5, 7])
        a = rng.randint(-1000, 1000)
        rows.append("%d %d" % (a, b))
    return {"name": "a mix of signs for a and b #%d" % index,
            "stdin": "\n".join(rows) + "\n"}
